import json
from pathlib import Path
wanted = {'OPEN-SOFTWARE-TENDERS-RETIRE', 'SOFTWARE-AWARD-LINK-REMOVAL', 'TEXT-CSV-INTAKE-EXPERIMENT'}
found = {}
for page in sorted(Path('world/pages').glob('missions-*.json')):
    def walk(value):
        if isinstance(value, dict):
            if value.get('mission_id') in wanted and 'goal' in value:
                found[value['mission_id']] = {key: value.get(key) for key in ('status', 'agent_id', 'goal', 'evidence')}
            for child in value.values():
                walk(child)
        elif isinstance(value, list):
            for child in value:
                walk(child)
    walk(json.loads(page.read_text()))
print(json.dumps({'missions': found, 'not_found_in_selected_pages': sorted(wanted - found.keys())}, indent=2))
